export interface WikiArticle {
  slug: string;
  title: string;
  category: string;
  summary: string;
  body: string;
  keywords?: string[];
  image?: string;
  sources?: string[];
}

const esc = (value: unknown) => String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]!);
const link = (slug: string, label: string) => `<a href="/${esc(slug)}/">${esc(label)}</a>`;
const p = (text: string) => `<p>${text}</p>`;
const h = (title: string) => `<h2>${esc(title)}</h2>`;
const list = (items: string[], ordered = false) => { const tag = ordered ? 'ol' : 'ul'; return `<${tag}>${items.map(item => `<li>${item}</li>`).join('')}</${tag}>`; };
const table = (headers: string[], rows: (string | number)[][]) => `<div class="table-scroll" role="region" aria-label="Scrollable reference table" tabindex="0"><table><thead><tr>${headers.map(head => `<th scope="col">${esc(head)}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const number = (value: number) => value.toLocaleString('en-US');
const seconds = (ms: number) => `${ms / 1000} s`;
const coordinates = (point: { x: number; z: number }) => `${Number(point.x.toFixed(1))}, ${Number(point.z.toFixed(1))}`;
const span = (values: number[]) => { const min = Math.min(...values), max = Math.max(...values); return min === max ? String(min) : `${min}–${max}`; };
const percent = (value: number) => `${Number((value * 100).toFixed(2))}%`;
const verdantMountOdds = `1 in ${number(VERDANT_REVENANT_DROP.oneIn)} (${percent(1 / VERDANT_REVENANT_DROP.oneIn)})`;
const oddsText = (odds: Readonly<Record<string, number>>) => Object.entries(odds).map(([quality, chance]) => `${quality[0].toUpperCase() + quality.slice(1)} ${percent(chance)}`).join(', ');
const maxEligibleBaseLevel = (sourceLevel: number) => Math.max(0, ...Object.values(GEAR).filter(gear => gear.price > 0 && gear.requiredLevel <= sourceLevel + 2).map(gear => gear.requiredLevel));
const zoneName = (id: ZoneId) => ZONES.find(zone => zone.id === id)!.name;
const regionName = (id: string) => id === COLOSSEUM.id ? COLOSSEUM.name : [...EXPEDITIONS, ...WILD_BIOMES].find(region => region.id === id)?.name ?? ZONES.find(zone => zone.id === id)?.name ?? id;
const regionLink = (id: string) => link(id === COLOSSEUM.id ? 'colosseum' : `region-${id}`, regionName(id));
const monsterLink = (id: EnemyKind) => link(`monster-${id}`, MONSTERS[id].name);
const nominalRange = (id: string) => `${REGION_LEVEL_RANGES[id].min}–${REGION_LEVEL_RANGES[id].max}`;
const statsText = (stats: StatBonuses) => Object.entries(stats).map(([key, value]) => `+${value}${key === 'speed' ? '%' : ''} ${{ primaryDamage: 'primary damage', specialDamage: 'special damage', damage: 'all damage', speed: 'movement speed' }[key] ?? key}`).join(', ');
const spawnLocations = OVERWORLD_SPAWNS.map(spawn => {
  const regionId = surfaceAt(spawn.x, spawn.z).regionId;
  return { ...spawn, regionId, level: monsterSpawnLevel(spawn, regionId) };
});
// Use the server's generated layout, including rich sites and shoreline fishing.
const nodeLocations = WORLD_GATHERING_NODES.map(node => ({ ...node, regionId: surfaceAt(node.x, node.z).regionId }));
const dungeonTable = () => table(['Dungeon', 'Entry level', 'Encounter levels', 'Entrance (x, z)', 'Completion reward'], DUNGEONS.map(dungeon => [link(`dungeon-${dungeon.id}`, dungeon.name), dungeon.minLevel, `${dungeon.minLevel}–${dungeon.maxLevel}`, `${regionLink(dungeon.entrance.zone)}<br>${coordinates(dungeon.entrance)}`, dungeon.storyQuestId ? 'One-time quest turn-in' : `${number(dungeon.completionXp)} XP`]));
const contractObjective = (contract: typeof CONTRACTS[number]) => {
  const target = contract.kind === 'kill' ? monsterLink(contract.target as EnemyKind) : contract.kind === 'gather' ? esc(RESOURCE_TYPES[contract.target as NodeKind].label) : contract.kind === 'craft' ? esc(RECIPES.find(recipe => recipe.id === contract.target)?.label ?? 'Any workshop recipe') : link('dungeon-rootvault', 'Rootvault clear');
  return `${contract.count} × ${target}${contract.targetLevel ? `, monster level ≥ ${contract.targetLevel}` : ''}${contract.targetRegion ? `<br>Only in ${regionLink(contract.targetRegion)}` : ''}`;
};
const contractTable = (contracts = CONTRACTS) => table(['Contract', 'Required level', 'Objective', 'XP', 'Gold', 'Repeat delay'], contracts.map(contract => [esc(contract.label), contract.requiredLevel ?? 1, contractObjective(contract), number(contract.reward.xp), goldSource(contract.reward.gold, 'contract', goldActive), `${contractCooldown(contract, goldActive) / 60000} min`]));
const resourceTable = (skill?: SkillId) => table(['Resource', 'Skill level', 'Yield', 'Base skill XP', 'Character XP', 'Base duration'], Object.values(RESOURCE_TYPES).filter(resource => !skill || resource.skill === skill).map(resource => [esc(resource.label), resource.requiredLevel, `${resource.yield} ${esc(resource.item ? LOOT_ITEMS[resource.item].label : resource.reward)}`, resource.xp, resource.adventureXp, seconds(resource.duration)]));
const rankTable = () => table(['Rank', 'Profession levels', 'Total XP to unlock'], PROFESSION_RANKS.map(rank => [rank.label, `${rank.level}–${rank.maxLevel}`, number(50 * (rank.level - 1) ** 2)]));
const professionXpGuide = () => p('Challenging work grants 100% of base skill XP, practiced work 60%, familiar work 25%, and mastered work 0%. Work becomes practiced halfway from its required level to the next rank, familiar at 80% of that interval, and mastered when the next rank unlocks. Artisan work becomes mastered at level 99. XP is rounded down and cannot exceed the skill cap. Mastered gathering still yields materials and character XP; mastered recipes still produce their items.');
const recipeTable = () => table(['Recipe', 'Crafting level', 'Character level', 'Discipline', 'Class', 'Materials', 'Output', 'Gold fee', 'Base crafting XP'], RECIPES.map(recipe => [esc(recipe.label), recipe.requiredCraftingLevel, recipe.requiredLevel, esc(recipe.discipline), recipe.className ?? 'Any', [...Object.entries(recipe.cost).map(([item, count]) => `${count} ${item}`), ...Object.entries(recipe.itemCost ?? {}).map(([item, count]) => `${count} ${esc(LOOT_ITEMS[item].label)}`)].join(', '), recipe.output.gear ? esc(GEAR[recipe.output.gear].label) : `${recipe.output.quantity} × ${esc(recipe.output.item ? LOOT_ITEMS[recipe.output.item].label : recipe.output.resource === 'potion' ? 'healing potion' : recipe.output.resource)}`, craftingGoldCost(recipe, goldActive), recipe.craftingXp]));
const creatureTable = (spawns: typeof spawnLocations) => table(['Creature', 'Actual spawn levels', 'Spawn count', 'Health range'], [...new Set(spawns.map(spawn => spawn.kind))].map(kind => {
  const entries = spawns.filter(spawn => spawn.kind === kind);
  return [monsterLink(kind), span(entries.map(spawn => spawn.level)), entries.length, span(entries.map(spawn => monsterStatsAtLevel(kind, spawn.level).hp))];
}));
const spawnTable = (spawns: typeof spawnLocations) => table(['Creature', 'Level', 'Region', 'Spawn (x, z)'], spawns.map(spawn => [monsterLink(spawn.kind), spawn.level, regionLink(spawn.regionId), coordinates(spawn)]));
const nodeTable = (nodes: typeof nodeLocations) => table(['Resource', 'Required skill', 'Node (x, z)'], nodes.map(node => [esc(RESOURCE_TYPES[node.kind].label), `${esc(SKILLS[RESOURCE_TYPES[node.kind].skill].label)} ${RESOURCE_TYPES[node.kind].requiredLevel}`, coordinates(node)]));
const details = (label: string, body: string) => `<details><summary>${esc(label)}</summary>${body}</details>`;
const classSummary: Record<CharacterClass, string> = {
  Ranger: 'Bow class. Starter ability: Quick Shot.', Knight: 'Sword class. Starter ability: Sword Strike.', Mage: 'Staff class. Starter ability: Fireball.', Cleric: 'Mace class. Starter ability: Smite.',
};
const sourcePaths = {
  monsters: ['src/bestiary.ts', 'src/region-levels.ts', 'src/realm.ts', 'src/settlements.ts', 'src/loot-items.ts', 'server.mjs'],
  dungeons: ['src/dungeon.ts', 'src/dungeon-mechanics.ts', 'src/dungeon-traps.ts', 'src/zones.ts', 'src/bestiary.ts', 'src/loot-items.ts', 'server.mjs'],
  regions: ['src/world-features.ts', 'src/content.ts', 'src/landscape.ts', 'src/region-levels.ts', 'src/bestiary.ts', 'src/realm.ts', 'src/settlements.ts', 'src/gathering-nodes.ts', 'src/adventure.ts', 'server.mjs'],
};
const level50Regions = Object.entries(REGION_LEVEL_RANGES).filter(([id, range]) => EXPEDITIONS.some(region => region.id === id) && range.max + 2 >= 50);
const level50RegionTable = () => table(['Region', 'Nominal monster levels', 'Monster levels for endgame gear', 'Maximum rolled gear level'], level50Regions.map(([id, range]) => [regionLink(id), `${range.min}–${range.max}`, `${Math.max(48, range.min)}–${range.max}`, Math.min(MAX_LEVEL, range.max + 2)]));
const gearDropTable = () => {
  const dungeonMaxLevel = Math.max(...DUNGEONS.filter(dungeon => !isThemedDungeonLoot(dungeon.id)).map(dungeon => dungeon.maxLevel));
  const dungeonBaseMax = maxEligibleBaseLevel(dungeonMaxLevel);
  const dungeonGearMax = dungeonBaseMax === 50 ? Math.min(MAX_LEVEL, dungeonMaxLevel + 2) : dungeonBaseMax;
  const bossMaxLevel = Math.max(...WORLD_BOSSES.map(boss => MONSTERS[boss.kind].level));
  const bossBaseMax = maxEligibleBaseLevel(bossMaxLevel);
  const epicPool = Object.values(GEAR).filter(gear => gear.price > 0 && gearLootQuality(gear) === 'epic' && gear.requiredLevel <= 50);
  const level50EpicShare = epicPool.filter(gear => gear.requiredLevel === 50).length / epicPool.length;
  const voidStalkerRareChance = LOOT_TABLES['void-stalker'].find(rule => rule.kind === 'gear' && rule.itemId === 'rare')?.chance ?? 0;
  const voidStalkerEpicChance = LOOT_TABLES['void-stalker'].find(rule => rule.kind === 'gear' && rule.itemId === 'epic')?.chance ?? 0;
  return table(['Source', 'Equipment roll', 'Rarity chances', 'Endgame result'], [
    ['Eligible overworld kill', `${percent(WORLD_GEAR_ROLL_CHANCE)} additional roll`, oddsText(WORLD_GEAR_ODDS), `Gear through level ${MAX_LEVEL}. Rare ${percent(WORLD_GEAR_ROLL_CHANCE * WORLD_GEAR_ODDS.rare)}; Epic ${percent(WORLD_GEAR_ROLL_CHANCE * WORLD_GEAR_ODDS.epic)} per kill`],
    ['Void Stalker in the level-50 areas', `${percent(voidStalkerEpicChance)} fixed Epic row`, 'Epic', `Its fixed ${percent(voidStalkerRareChance)} Rare row selects the level-25 Rare band; up to ${percent(voidStalkerEpicChance * level50EpicShare)} selects level-50 Epic`],
    ['Original four dungeons: monster', `${percent(DUNGEON_GEAR_ROLL_CHANCE)} additional roll`, oddsText(DUNGEON_GEAR_ODDS), `Base gear tiers through level ${dungeonGearMax}, limited by character level and encounter level + 2`],
    ['Original four dungeons: cache or completion', `${percent(LEGACY_DUNGEON_GEAR_DROP_CHANCE)} chance for 1 gear item`, oddsText(DUNGEON_CACHE_ODDS), `Base gear tiers through level ${dungeonGearMax}, limited by character level and dungeon maximum level + 2`],
    ['Plagueworks, Emberfall, Veilhaven: monster', `${percent(DUNGEON_GEAR_ROLL_CHANCE)} additional roll`, oddsText(DUNGEON_GEAR_ODDS), 'Gear matches encounter level, capped at your character level'],
    ['Themed dungeon side cache', `${percent(DUNGEON_GEAR_DROP_CHANCES.cache)} chance for 1 gear item`, oddsText(DUNGEON_CACHE_ODDS), 'Gear matches its guarded encounter level, capped at your character level'],
    ['Themed dungeon midpoint boss', `${percent(DUNGEON_GEAR_DROP_CHANCES.midpoint)} chance for 1 gear item`, oddsText(DUNGEON_MIDPOINT_ODDS), 'Gear matches boss level, capped at your character level'],
    ['Themed dungeon final completion', `${percent(DUNGEON_GEAR_DROP_CHANCES.final)} chance for 1 gear item`, oddsText(DUNGEON_FINAL_ODDS), 'Gear matches final boss level, capped at your character level'],
    ['World boss', `${percent(WORLD_GEAR_ROLL_CHANCE)} additional roll plus fixed boss rows`, oddsText(WORLD_GEAR_ODDS), `No level-50 gear; current highest eligible base level is ${bossBaseMax}`],
  ]);
};

