      + (boss ? p(`Fixed level ${monster.level}. Kill loot includes ${boss.relic} relic${boss.relic === 1 ? '' : 's'}. Respawn delay: ${boss.respawnMs / 60000} minutes.`) : p(`Base values above exclude ordinary monster level scaling and dungeon modifiers. ${spawns.length ? `The actual initial overworld health range for this creature is ${span(spawns.map(spawn => monsterStatsAtLevel(kind, spawn.level).hp))} HP.` : 'See the dungeon encounter table for its level.'}`))
      + (spawns.length ? h('Overworld locations') + table(['Area', 'Actual levels', 'Spawns', 'Initial health'], locations.map(id => { const entries = spawns.filter(spawn => spawn.regionId === id); return [regionLink(id), span(entries.map(spawn => spawn.level)), entries.length, span(entries.map(spawn => monsterStatsAtLevel(kind, spawn.level).hp))]; }))
      + details('Spawn coordinates', spawnTable(spawns)) : p('This creature is found in dungeon instances; defeated encounters stay cleared until the run resets.'))
